// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns

// EVOLVE-BLOCK-START
pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    let len = arr.len();
    if len <= 1 { return; }
    if len <= 32 { insertion_sort(arr); return; }
    // Check if nearly sorted: use insertion sort
    let mut runs = 0;
    for i in 1..len {
        if arr[i] < arr[i - 1] { runs += 1; }
    }
    if runs <= len / 8 {
        insertion_sort(arr);
    } else {
        let max_depth = (2.0 * (len as f64).log2()) as usize;
        introsort(arr, 0, len - 1, max_depth);
    }
}

fn introsort<T: Ord + Clone>(arr: &mut [T], low: usize, high: usize, depth: usize) {
    if high <= low { return; }
    let len = high - low + 1;
    if len <= 24 { insertion_sort_range(arr, low, high); return; }
    if depth == 0 { heapsort_range(arr, low, high); return; }
    let p = partition(arr, low, high);
    if p > 0 { introsort(arr, low, p - 1, depth - 1); }
    introsort(arr, p + 1, high, depth - 1);
}

fn partition<T: Ord + Clone>(arr: &mut [T], low: usize, high: usize) -> usize {
    let mid = low + (high - low) / 2;
    // Median-of-three pivot
    if arr[mid] < arr[low] { arr.swap(low, mid); }
    if arr[high] < arr[low] { arr.swap(low, high); }
    if arr[mid] < arr[high] { arr.swap(mid, high); }
    let pivot = arr[high].clone();
    let mut i = low;
    for j in low..high {
        if arr[j] <= pivot { arr.swap(i, j); i += 1; }
    }
    arr.swap(i, high);
    i
}

fn insertion_sort<T: Ord>(arr: &mut [T]) {
    for i in 1..arr.len() {
        let mut j = i;
        while j > 0 && arr[j - 1] > arr[j] { arr.swap(j, j - 1); j -= 1; }
    }
}

fn insertion_sort_range<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    for i in (low + 1)..=high {
        let mut j = i;
        while j > low && arr[j - 1] > arr[j] { arr.swap(j, j - 1); j -= 1; }
    }
}

fn heapsort_range<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    let n = high - low + 1;
    for i in (0..n / 2).rev() { sift_down(arr, i, n - 1, low); }
    for i in (1..n).rev() {
        arr.swap(low, low + i);
        sift_down(arr, 0, i - 1, low);
    }
}

fn sift_down<T: Ord>(arr: &mut [T], start: usize, end: usize, offset: usize) {
    let mut root = start;
    loop {
        let mut child = 2 * root + 1;
        if child > end { break; }
        if child + 1 <= end && arr[offset + child] < arr[offset + child + 1] { child += 1; }
        if arr[offset + root] < arr[offset + child] {
            arr.swap(offset + root, offset + child);
            root = child;
        } else { break; }
    }
}
